import { useCallback, useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
  locale?: string;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

const QUICK_OPTIONS: ReadonlyArray<{ label: string; offsetDays: number }> = [
  { label: 'Сегодня', offsetDays: 0 },
  { label: 'Вчера', offsetDays: -1 },
  { label: 'Неделя назад', offsetDays: -7 },
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, days: number): Date {
  const next = startOfDay(date);
  next.setDate(next.getDate() + days);
  return next;
}

function addMonths(date: Date, months: number): Date {
  return new Date(date.getFullYear(), date.getMonth() + months, 1);
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function buildMonthGrid(month: Date): Date[] {
  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  // Сдвиг к понедельнику: getDay() отдаёт 0 для воскресенья
  const shift = (first.getDay() + 6) % 7;
  const gridStart = addDays(first, -shift);
  return Array.from({ length: 42 }, (_, index) => addDays(gridStart, index));
}

function ReportDatePicker({ value, onChange, locale = 'ru-RU' }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalValue, setInternalValue] = useState<Date>(() =>
    value ? startOfDay(value) : today,
  );

  const selected = value ? startOfDay(value) : internalValue;
  const [viewMonth, setViewMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const monthLabel = useMemo(
    () =>
      new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(viewMonth),
    [locale, viewMonth],
  );

  const days = useMemo(() => buildMonthGrid(viewMonth), [viewMonth]);

  const selectDate = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setInternalValue(normalized);
      setViewMonth(new Date(normalized.getFullYear(), normalized.getMonth(), 1));
      onChange(normalized);
    },
    [onChange],
  );

  const gridStyle = {
    display: 'grid',
    gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
    gap: 'var(--jx-space-1)',
  } as const;

  return (
    <Card padding="md">
      <Stack direction="column" gap="md">
        <Stack direction="row" gap="sm" wrap>
          {QUICK_OPTIONS.map((option) => {
            const optionDate = addDays(today, option.offsetDays);
            return (
              <Button
                key={option.label}
                type="button"
                size="sm"
                variant={isSameDay(optionDate, selected) ? 'primary' : 'outline'}
                onClick={() => selectDate(optionDate)}
              >
                {option.label}
              </Button>
            );
          })}
        </Stack>

        <Stack direction="row" gap="sm" align="center" justify="space-between">
          <Button
            type="button"
            size="sm"
            variant="ghost"
            aria-label="Предыдущий месяц"
            onClick={() => setViewMonth((current) => addMonths(current, -1))}
          >
            ‹
          </Button>
          <Text weight="medium">{monthLabel}</Text>
          <Button
            type="button"
            size="sm"
            variant="ghost"
            aria-label="Следующий месяц"
            onClick={() => setViewMonth((current) => addMonths(current, 1))}
          >
            ›
          </Button>
        </Stack>

        <div style={gridStyle}>
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" align="center" style={{ color: 'var(--jx-color-text-muted)' }}>
              {weekday}
            </Text>
          ))}
        </div>

        <div style={gridStyle} role="grid" aria-label="Календарь на месяц">
          {days.map((day) => {
            const isCurrentMonth = day.getMonth() === viewMonth.getMonth();
            const isSelected = isSameDay(day, selected);
            return (
              <Button
                key={day.toISOString()}
                type="button"
                size="sm"
                fullWidth
                role="gridcell"
                aria-selected={isSelected}
                variant={isSelected ? 'primary' : isSameDay(day, today) ? 'outline' : 'ghost'}
                style={
                  isCurrentMonth || isSelected
                    ? undefined
                    : { color: 'var(--jx-color-text-muted)' }
                }
                onClick={() => selectDate(day)}
              >
                {day.getDate()}
              </Button>
            );
          })}
        </div>
      </Stack>
    </Card>
  );
}

export default ReportDatePicker;

